/**
 * Renders the two generated license sections of `docs/ui-components.md`.
 *
 * That file is handed to the customer, so both tables are generated rather than
 * maintained: a hand-kept list of 44 packages and 127 transitive ones is a
 * promise nobody can keep, and a stale one is worse than none.
 *
 * Kept out of the verification module so the policy rules and their
 * presentation can be read separately.
 */

import { ALLOWED_DEP_LICENSES } from "./dependency-licenses.mjs";
import { groupByLicense } from "./transitive-dependencies.mjs";

const DO_NOT_EDIT =
  "_Generated by `scripts/check-provenance.mjs`. Do not edit by hand — run `npm run licenses:sync` after changing a dependency, then `npm run check:provenance`._";

/** Declared packages: what each item installs, and which items bring it. */
export function renderDependencySection(deps, table) {
  const rows = deps.map(({ name, ranges, items }) => {
    const record = table[name] ?? {};
    const notice = record.notice ? " (ships a NOTICE)" : "";
    const carriers = [...new Set(items)].sort().map((i) => `\`${i}\``).join(", ");
    return `| \`${name}\` | ${[...ranges].sort().join(", ") || "—"} | ${record.license ?? "—"}${notice} | ${carriers} |`;
  });

  return [
    DO_NOT_EDIT,
    "",
    `Allowed: ${[...ALLOWED_DEP_LICENSES].map((l) => `\`${l}\``).join(", ")}. Anything else fails CI.`,
    "",
    "| Package | Range installed | License | Arrives with |",
    "|---|---|---|---|",
    ...rows,
  ].join("\n");
}

/**
 * The transitive closure, grouped by license rather than listed package by
 * package.
 *
 * MIT is the ecosystem default and its members are counted rather than named —
 * a reviewer opening this section is looking for what is *not* MIT, and burying
 * sixteen interesting names under a hundred unsurprising ones hides them.
 */
export function renderClosureSection(deps, closure) {
  const groups = groupByLicense(closure.packages);
  const rows = groups.map(({ license, names }) => {
    const listed = license === "MIT" ? "—" : names.map((n) => `\`${n}\``).join(", ");
    return `| ${license} | ${names.length} | ${listed} |`;
  });

  return [
    DO_NOT_EDIT,
    "",
    `The ${deps.length} packages above pull in **${closure.packages.length} in total**, counting runtime dependencies only. Resolved from this repository's \`package-lock.json\`.`,
    "",
    "| License | Packages | Which |",
    "|---|---|---|",
    ...rows,
    "",
    "MIT members are counted rather than listed; everything else is named.",
  ].join("\n");
}
